// --- START OF FILE ModelViewer.js ---
import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';

const ModelViewer = ({ modelPath, alt = '3D Model' }) => {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const [status, setStatus] = useState('loading');
  const [errorMsg, setErrorMsg] = useState('');
  
  const controlsRef = useRef(null);
  const cameraRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    // 1. 初始化渲染器
    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: true,
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    
    // 【修复3：光照过亮】降低曝光度，保留高光细节
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.7; // 从 1.0 降至 0.7，防止过曝

    // 2. 初始化场景
    const scene = new THREE.Scene();
    scene.background = new THREE.Color('#1a1b1e'); 

    // 3. 生成 HDRI 环境贴图
    const pmremGenerator = new THREE.PMREMGenerator(renderer);
    const envTexture = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;
    scene.environment = envTexture;

    // 4. 初始化相机
    const camera = new THREE.PerspectiveCamera(45, container.clientWidth / container.clientHeight, 0.1, 100);
    camera.position.set(4, 3, 5);
    cameraRef.current = camera;

    // 5. 初始化控制器
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 1.5;
    controls.minDistance = 0.5;
    controls.maxDistance = 20;
    controlsRef.current = controls;

    // 6. 加载模型
    const loader = new GLTFLoader();
    const resolvedPath = modelPath.startsWith('http')
      ? modelPath
      : `${(process.env.PUBLIC_URL || '').replace(/\/+$/, '')}/${modelPath.replace(/^\/+/, '')}`;

    loader.load(
      resolvedPath,
      (gltf) => {
        const model = gltf.scene;

        // 居中与统一缩放逻辑
        const box = new THREE.Box3().setFromObject(model);
        const center = box.getCenter(new THREE.Vector3());
        const size = box.getSize(new THREE.Vector3());
        const maxDim = Math.max(size.x, size.y, size.z);

        const wrapper = new THREE.Group();
        model.position.set(-center.x, -center.y, -center.z);
        wrapper.add(model);
        
        const scale = 2.5 / maxDim;
        wrapper.scale.setScalar(scale);
        scene.add(wrapper);

        // 遍历并修复网格与材质
        model.traverse((child) => {
          if (child.isMesh) {
            
            // 【修复1：面饼网格化】强制重新计算平滑法线
            // 无论 Blender 是否导出了平滑法线，这里强制在前端进行一次圆滑处理
            child.geometry.computeVertexNormals();

            if (child.material) {
              const materials = Array.isArray(child.material) ? child.material : [child.material];
              
              materials.forEach((mat, index) => {
                let physMat = mat;
                
                if (mat.isMeshStandardMaterial && !mat.isMeshPhysicalMaterial) {
                  physMat = new THREE.MeshPhysicalMaterial();
                  
                  // 安全拷贝属性
                  for (const key in mat) {
                    if (
                      key !== 'type' && key !== 'id' && key !== 'uuid' &&
                      typeof mat[key] !== 'function' &&
                      physMat[key] !== undefined
                    ) {
                      if (mat[key] && typeof mat[key].copy === 'function' && (mat[key].isColor || mat[key].isVector2 || mat[key].isVector3)) {
                        physMat[key].copy(mat[key]);
                      } else {
                        physMat[key] = mat[key];
                      }
                    }
                  }
                  // 【关键】必须显式继承顶点颜色，防止几何节点生成的糖针丢失颜色
                  physMat.vertexColors = mat.vertexColors;
                  physMat.flatShading = false; // 确保关闭平直着色
                  
                  if (Array.isArray(child.material)) {
                    child.material[index] = physMat;
                  } else {
                    child.material = physMat;
                  }
                }

                const name = (physMat.name || child.name || '').toLowerCase();
                const isIcing = /icing|frosting|glaze|sugar|candy/.test(name);
                
                if (isIcing) {
                  // 【修复2：缺少巧克力】
                  // 将透光率 (transmission) 从 0.8 降到 0.3，模拟“浓稠的糖浆”而非“透明玻璃”
                  // 这样能修复 Three.js 的深度剔除 Bug，让包裹在内部的巧克力点重新显现
                  physMat.transmission = 0.3;      
                  physMat.thickness = 0.5;         
                  physMat.attenuationDistance = 0.1; 
                  physMat.attenuationColor = new THREE.Color(0xffc0cb); 
                  physMat.roughness = Math.max(0.15, physMat.roughness || 0); // 略微增加粗糙度，避免反光死白
                  physMat.ior = 1.45;
                  physMat.transparent = false; // 强制关闭常规透明度，完全交由 transmission 计算物理折射
                  physMat.depthWrite = true;   // 强制写入深度缓冲，保护巧克力点
                }
                
                physMat.envMapIntensity = 0.8; // 略微调低环境反射强度，配合曝光度降低过曝
                physMat.needsUpdate = true;
              });
            }
          }
        });

        // 底部辅助网格
        const gridHelper = new THREE.GridHelper(4, 20, 0x444466, 0x222233);
        gridHelper.position.y = -size.y * scale / 2; 
        scene.add(gridHelper);

        setStatus('loaded');
        
        // 自动调整舒适的观看距离
        const dist = maxDim * scale * 1.8;
        camera.position.set(dist * 0.8, dist * 0.6, dist);
        controls.target.set(0, 0, 0);
        controls.update();
      },
      (progress) => {
        if (progress.total > 0) {
          const pct = Math.round((progress.loaded / progress.total) * 100);
          setStatus(`loading-${pct}`);
        }
      },
      (error) => {
        console.error('[ModelViewer] Load Error:', error);
        setStatus('error');
        setErrorMsg(error.message);
      }
    );

    // 7. 处理窗口响应
    const handleResize = () => {
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener('resize', handleResize);

    // 8. 动画循环
    let reqId;
    const animate = () => {
      reqId = requestAnimationFrame(animate);
      controls.update();
      renderer.render(scene, camera);
    };
    animate();

    // 9. 清理函数
    return () => {
      cancelAnimationFrame(reqId);
      window.removeEventListener('resize', handleResize);
      pmremGenerator.dispose();
      renderer.dispose();
      controls.dispose();
    };
  }, [modelPath]);

  // 控制按钮回调
  const toggleAutoRotate = () => {
    if (controlsRef.current) controlsRef.current.autoRotate = !controlsRef.current.autoRotate;
  };
  const resetView = () => {
    if (cameraRef.current && controlsRef.current) {
      cameraRef.current.position.set(4, 3, 5);
      controlsRef.current.target.set(0, 0, 0);
    }
  };

  const isLoading = status === 'loading' || status.startsWith('loading-');
  const loadProgress = status.startsWith('loading-') ? parseInt(status.split('-')[1], 10) : 0;

  return (
    <div
      ref={containerRef}
      style={{
        position: 'relative', width: '100%', minHeight: '400px', borderRadius: '12px',
        overflow: 'hidden', border: '1px solid var(--border)', background: '#1a1b1e', margin: '20px 0',
      }}
    >
      <canvas ref={canvasRef} style={{ width: '100%', height: '100%', display: 'block' }} />

      {isLoading && (
        <div style={overlayStyle}>
          <div style={spinnerStyle} />
          <div style={{ marginTop: '12px', fontSize: '0.85rem', opacity: 0.8 }}>
            {loadProgress > 0 ? `加载中 ${loadProgress}%` : '加载模型中...'}
          </div>
        </div>
      )}

      {status === 'error' && (
        <div style={{ ...overlayStyle, background: 'rgba(0,0,0,0.8)' }}>
          <div style={{ color: '#ff5555', fontSize: '2rem', marginBottom: '8px' }}>⚠️</div>
          <div style={{ color: '#ff8888', fontSize: '0.9rem', marginBottom: '12px' }}>{errorMsg || '加载失败'}</div>
        </div>
      )}

      {status === 'loaded' && (
        <div style={{ position: 'absolute', bottom: '12px', left: 0, right: 0, display: 'flex', justifyContent: 'center', pointerEvents: 'none' }}>
          <div style={{ display: 'flex', gap: '6px', pointerEvents: 'auto', background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(8px)', borderRadius: '8px', padding: '6px 10px' }}>
            <button onClick={toggleAutoRotate} style={controlBtnStyle} title="切换自动旋转">⟳</button>
            <button onClick={resetView} style={controlBtnStyle} title="重置视角">⊞</button>
            <span style={{ fontSize: '0.65rem', color: '#4fc3f7', padding: '2px 6px', background: 'rgba(79,195,247,0.15)', borderRadius: '4px', display: 'flex', alignItems: 'center' }}>
              WebGL2 PBR
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

const overlayStyle = { position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: 'rgba(26,27,30,0.85)', color: '#e2e2e4', zIndex: 10 };
const spinnerStyle = { width: '40px', height: '40px', border: '3px solid rgba(255,255,255,0.1)', borderTopColor: '#4f46e5', borderRadius: '50%', animation: 'spin 0.8s linear infinite' };
const controlBtnStyle = { width: '32px', height: '32px', background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.2)', borderRadius: '6px', cursor: 'pointer', color: '#e2e2e4', display: 'flex', alignItems: 'center', justifyContent: 'center' };

export default ModelViewer;
// --- END OF FILE ModelViewer.js ---